                while dq:
                    a,b=dq.popleft(); cells.append((a,b))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        nr,nc=a+dr,b+dc
                        if 0<=nr<H and 0<=nc<W and mask[nr,nc] and not seen[nr,nc]:
                            seen[nr,nc]=True; dq.append((nr,nc))
                res.append(cells)
    return res
